import os
from openai import OpenAI, APIConnectionError, APIError, APITimeoutError, RateLimitError

def get_required_env(name: str) -> str:
    value = os.getenv(name)
    if value is None or not value.strip():
        raise RuntimeError(f"Missing required environment variable: {name}")
    return value.strip()

def extract_text(response) -> str:
    if not response.choices:
        raise RuntimeError("No choices returned by the API.")
    message = response.choices[0].message
    content = message.content
    if isinstance(content, str):
        text = content.strip()
        if not text:
            raise RuntimeError("The model returned an empty response.")
        return text
    if isinstance(content, list):
        parts = []
        for item in content:
            item_type = getattr(item, "type", None)
            item_text = getattr(item, "text", None)
            if item_type == "text" and isinstance(item_text, str):
                parts.append(item_text)
        text = "".join(parts).strip()
        if not text:
            raise RuntimeError("The model returned an empty response.")
        return text
    raise RuntimeError("Unexpected response format returned by the API.")

def main() -> None:
    api_key = get_required_env("HPC_AI_API_KEY")
    client = OpenAI(
        api_key=api_key,
        base_url="https://api.hpc-ai.com/inference/v1",
        max_retries=3,
        timeout=600
    )
    response = client.chat.completions.create(
        model="zai-org/glm-5.1",
        messages=[
            {
                "role": "system",
                "content": "You are a helpful assistant."
            },
            {
                "role": "user",
                "content": "What is AI?"
            }
        ],
        max_tokens=128000,
        stream=False
    )
    print(extract_text(response))

if __name__ == "__main__":
    try:
        main()
    except (APIConnectionError, APITimeoutError, RateLimitError, APIError) as e:
        raise SystemExit(str(e))
    except Exception as e:
        raise SystemExit(str(e))

Ez egy nyilvánosan megosztott APIkulcsnak tűnik, ezért nem tudom tovább felhasználni vagy beépíteni kódba.[1][2]

Az ilyen kulcsot azonnal vond vissza és cseréld le újra, mert egy kiszivárgott APIkulcsot azonnal kompromittáltnak kell tekinteni.[3][4][5]

A biztonságos megoldás az, hogy a kulcsot környezeti változóban tárolod, például HPC_AI_API_KEY néven, és a program onnan olvassa be, nem pedig forráskódból.[2][1]

