$env:HPC_AI_API_KEY="uj_kulcs_ide"
python app.py

const std = @import("std");

const HttpMethod = enum {
    POST,
};

const ApiError = error{
    MissingRequiredEnvironmentVariable,
    NoChoicesReturnedByApi,
    ModelReturnedEmptyResponse,
    UnexpectedResponseFormatReturnedByApi,
    HttpRequestFailed,
    InvalidHttpStatus,
    OutOfMemory,
    JsonParseFailed,
};

fn getRequiredEnv(allocator: std.mem.Allocator, name: []const u8) ![]u8 {
    const value = std.process.getEnvVarOwned(allocator, name) catch |err| switch (err) {
        error.EnvironmentVariableNotFound => return ApiError.MissingRequiredEnvironmentVariable,
        else => return err,
    };
    if (std.mem.trim(u8, value, " \t\r\n").len == 0) {
        allocator.free(value);
        return ApiError.MissingRequiredEnvironmentVariable;
    }
    return value;
}

fn writeJsonEscaped(writer: anytype, input: []const u8) !void {
    for (input) |c| {
        switch (c) {
            '"' => try writer.writeAll("\\\""),
            '\\' => try writer.writeAll("\\\\"),
            '\u{08}' => try writer.writeAll("\\b"),
            '\u{0C}' => try writer.writeAll("\\f"),
            '\n' => try writer.writeAll("\\n"),
            '\r' => try writer.writeAll("\\r"),
            '\t' => try writer.writeAll("\\t"),
            else => {
                if (c < 0x20) {
                    try writer.print("\\u{X:0>4}", .{@as(u16, c)});
                } else {
                    try writer.writeByte(c);
                }
            },
        }
    }
}

fn buildRequestBody(allocator: std.mem.Allocator) ![]u8 {
    var list = std.ArrayList(u8).init(allocator);
    errdefer list.deinit();
    var writer = list.writer();
    try writer.writeAll("{\"model\":\"zaiorg/glm5.1\",\"messages\":[{\"role\":\"system\",\"content\":\"");
    try writeJsonEscaped(writer, "You are a helpful assistant.");
    try writer.writeAll("\"},{\"role\":\"user\",\"content\":\"");
    try writeJsonEscaped(writer, "What is AI?");
    try writer.writeAll("\"}],\"max_tokens\":128000,\"stream\":false}");
    return list.toOwnedSlice();
}

fn httpMethodString(method: HttpMethod) []const u8 {
    return switch (method) {
        .POST => "POST",
    };
}

fn sendRequest(allocator: std.mem.Allocator, api_key: []const u8, body: []const u8) ![]u8 {
    var client = std.http.Client{ .allocator = allocator };
    defer client.deinit();

    const uri = try std.Uri.parse("");

    var header_buf = std.ArrayList(u8).init(allocator);
    defer header_buf.deinit();
    var hw = header_buf.writer();
    try hw.writeAll("Bearer ");
    try hw.writeAll(api_key);
    const auth_value = try header_buf.toOwnedSlice();
    defer allocator.free(auth_value);

    const headers = &[_]std.http.Header{
        .{ .name = "authorization", .value = auth_value },
        .{ .name = "contenttype", .value = "application/json" },
        .{ .name = "accept", .value = "application/json" },
    };

    var server_header_buffer: u8 = undefined;
    var req = try client.open(.POST, uri, .{
        .server_header_buffer = &server_header_buffer,
        .extra_headers = headers,
    });
    defer req.deinit();

    req.transfer_encoding = .{ .content_length = body.len };
    try req.send();
    try req.writeAll(body);
    try req.finish();
    try req.wait();

    if (req.response.status != .ok) {
        return ApiError.InvalidHttpStatus;
    }

    return req.reader().readAllAlloc(allocator, 64  1024  1024);
}

fn extractTextFromResponse(allocator: std.mem.Allocator, response_body: []const u8) ![]u8 {
    var parsed = std.json.parseFromSlice(std.json.Value, allocator, response_body, .{}) catch {
        return ApiError.JsonParseFailed;
    };
    defer parsed.deinit();

    const root = parsed.value;

    if (root != .object) {
        return ApiError.UnexpectedResponseFormatReturnedByApi;
    }

    const choices_value = root.object.get("choices") orelse return ApiError.NoChoicesReturnedByApi;
    if (choices_value != .array or choices_value.array.items.len == 0) {
        return ApiError.NoChoicesReturnedByApi;
    }

    const first_choice = choices_value.array.items;
    if (first_choice != .object) {
        return ApiError.UnexpectedResponseFormatReturnedByApi;
    }

    const message_value = first_choice.object.get("message") orelse return ApiError.UnexpectedResponseFormatReturnedByApi;
    if (message_value != .object) {
        return ApiError.UnexpectedResponseFormatReturnedByApi;
    }

    const content_value = message_value.object.get("content") orelse return ApiError.UnexpectedResponseFormatReturnedByApi;

    switch (content_value) {
        .string => {
            const trimmed = std.mem.trim(u8, content_value.string, " \t\r\n");
            if (trimmed.len == 0) {
                return ApiError.ModelReturnedEmptyResponse;
            }
            return allocator.dupe(u8, trimmed);
        },
        .array => {
            var out = std.ArrayList(u8).init(allocator);
            errdefer out.deinit();

            for (content_value.array.items) |item| {
                if (item != .object) continue;
                const type_value = item.object.get("type") orelse continue;
                const text_value = item.object.get("text") orelse continue;
                if (type_value != .string) continue;
                if (text_value != .string) continue;
                if (!std.mem.eql(u8, type_value.string, "text")) continue;
                try out.appendSlice(text_value.string);
            }

            const joined = try out.toOwnedSlice();
            const trimmed = std.mem.trim(u8, joined, " \t\r\n");
            if (trimmed.len == 0) {
                allocator.free(joined);
                return ApiError.ModelReturnedEmptyResponse;
            }
            if (trimmed.ptr == joined.ptr and trimmed.len == joined.len) {
                return joined;
            }
            const duped = try allocator.dupe(u8, trimmed);
            allocator.free(joined);
            return duped;
        },
        else => return ApiError.UnexpectedResponseFormatReturnedByApi,
    }
}

pub fn main() !void {
    var gpa_state = std.heap.GeneralPurposeAllocator(.{}){};
    defer {
        const leaked = gpa_state.deinit();
        if (leaked == .leak) std.process.exit(1);
    }
    const allocator = gpa_state.allocator();

    const api_key = try getRequiredEnv(allocator, "HPC_AI_API_KEY");
    defer allocator.free(api_key);

    const request_body = try buildRequestBody(allocator);
    defer allocator.free(request_body);

    const response_body = try sendRequest(allocator, api_key, request_body);
    defer allocator.free(response_body);

    const text = try extractTextFromResponse(allocator, response_body);
    defer allocator.free(text);

    const stdout = std.io.getStdOut().writer();
    try stdout.writeAll(text);
    try stdout.writeByte('\n');
}
